	"reflect"
	"runtime"
	"strings"
	"testing"
	"time"
)

func TestGetAgentResultConcurrentCompletion(t *testing.T) {
	for _, fail := range []bool{false, true} {
		name := "completed"
		if fail {
			name = "failed"
		}
		t.Run(name, func(t *testing.T) {
			ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
			defer cancel()
			manager := NewAgentManager()
			agent := &AgentState{ID: "child", Status: AgentStatusRunning, done: make(chan struct{})}
			manager.Register(agent)
			fragment := NewEmptyFragment().AddMessage(AssistantMessageRole, "answer")
			spawn := &spawnAgentRunner{manager: manager, dispatcher: func(context.Context, AgentRunSpec) (Fragment, error) {
				if fail {
					return Fragment{}, errors.New("boom")
				}
				return fragment, nil
			}}
			type response struct {
				text string
				data any
				err  error
			}
			got := make(chan response, 1)
			go func() {
				runner := &getAgentResultRunner{manager: manager, ctx: ctx}
				text, data, err := runner.Run(GetAgentResultArgs{AgentID: agent.ID, Wait: true})
				got <- response{text, data, err}
			}()

			// Observe the reader parked in its select without creating a
			// happens-before edge from its status read to runAgent's write.
			// A channel handshake here would hide the original data race.
			stack := make([]byte, 1<<20)
			for {
				n := runtime.Stack(stack, true)
				waiting := false
				for _, goroutine := range strings.Split(string(stack[:n]), "\n\n") {
					if strings.Contains(goroutine, "[select]") && strings.Contains(goroutine, "(*getAgentResultRunner).Run(") {
						waiting = true
						break
					}
				}
				if waiting {
					break
				}
				if ctx.Err() != nil {
					t.Fatal("result reader did not reach its completion wait")
				}
				runtime.Gosched()
			}

			go spawn.runAgent(agent, nil, Fragment{}, nil, AgentRunSpec{}, ctx, func() {})
			select {
			case result := <-got:
				want := "answer"
				if fail {
					want = "Agent child failed: boom"
				}
				if result.err != nil || result.text != want {
					t.Fatalf("result = %q, %v; want %q, nil", result.text, result.err, want)
				}
				if fail {
					if result.data != nil {
						t.Fatalf("failed result data = %v, want nil", result.data)
					}
				} else if !reflect.DeepEqual(result.data, agent.Fragment) || agent.Fragment.LastMessage().Content != "answer" {
					t.Fatalf("result fragment = %v, want completed fragment", result.data)
				}
			case <-ctx.Done():
				t.Fatal("completion blocked: result reader must not hold the manager lock while waiting")
			}
		})
	}
}

package cogito

import (
	"context"
	"testing"
	"time"
)

// TestDetachedAgentSurvivesParentCancel verifies that once a foreground
// sub-agent is detached to the background, cancelling the parent turn's context
// (as an embedder does when its ExecuteTools call returns) does NOT cancel the
// detached agent: it keeps running and completes its work.
//
// Regression: previously the sub-agent context was a child of r.ctx, so the
// embedder cancelling the per-turn context killed the just-detached agent.
func TestDetachedAgentSurvivesParentCancel(t *testing.T) {
	m := NewAgentManager()
	release := make(chan struct{})
	llm := newBlockingLLM(release)

	parentCtx, cancelParent := context.WithCancel(context.Background())
	runner := &spawnAgentRunner{llm: llm, manager: m, ctx: parentCtx}

	idCh := make(chan any, 1)
	go func() {
		_, id, _ := runner.Run(SpawnAgentArgs{Task: "long job", Background: false})
		idCh <- id
	}()

	// Wait for the foreground agent to register, then detach it.
	var id string
	deadline := time.After(2 * time.Second)
	for id == "" {
		if agents := m.List(); len(agents) == 1 {
			id = agents[0].ID
			break
		}
		select {
		case <-deadline:
			t.Fatal("foreground agent never registered")
		case <-time.After(10 * time.Millisecond):
		}
	}
	if err := m.Detach(id); err != nil {
		t.Fatalf("detach errored: %v", err)
	}
	if rid := <-idCh; rid == nil {
		t.Fatal("expected detach to return the agent id")
	}

	// Simulate the embedder cancelling the per-turn context now that the parent
	// ExecuteTools call has returned. The detached agent must survive this.
	cancelParent()

	// Give any erroneous cancellation a chance to propagate, then let the agent
	// finish its work.
	time.Sleep(50 * time.Millisecond)
	close(release)

	// Wait uses a synchronized lifecycle snapshot, not a live record.
	completed := make(chan *AgentState, 1)
	go func() { a, _ := m.Wait(id); completed <- a }()
	select {
	case a := <-completed:
		if a.Status != AgentStatusCompleted || a.Result != llm.reply {
			t.Fatalf("detached result: status=%s result=%q error=%v", a.Status, a.Result, a.Error)
		}
	case <-time.After(2 * time.Second):
		t.Fatal("detached agent did not complete after parent cancel")
	}
}

