)

// TestContentToStringImageDoesNotPanic pins the fix for the crash reported in
// mudler/LocalAI#10101: an MCP tool that returns a non-text content block (e.g.
// an image from osmmcp's get_map_image) used to make contentToString panic with
// "interface conversion: mcp.Content is *mcp.ImageContent, not *mcp.TextContent",
// taking the whole process down. Mixed text + image content must be handled
// gracefully instead.
func TestContentToStringImageDoesNotPanic(t *testing.T) {
	content := []mcp.Content{
		&mcp.TextContent{Text: "here is your map: "},
		&mcp.ImageContent{MIMEType: "image/png", Data: []byte("\x89PNGfakebytes")},
	}

	result := contentToString(content)

	// The text block must still be preserved verbatim.
	if !strings.Contains(result, "here is your map: ") {
		t.Fatalf("expected text content to be preserved, got %q", result)
	}
	// The image block must contribute a descriptive, non-empty marker rather
	// than panicking or being silently lost, so the model knows an image came back.
	if !strings.Contains(result, "image/png") {
		t.Fatalf("expected image mime type to surface in result, got %q", result)
	}
}

// TestContentToStringTextOnly pins the original behavior: plain text blocks are
// concatenated verbatim with no extra decoration.
func TestContentToStringTextOnly(t *testing.T) {
	content := []mcp.Content{
		&mcp.TextContent{Text: "hello "},
		&mcp.TextContent{Text: "world"},
	}

	if got := contentToString(content); got != "hello world" {
		t.Fatalf("expected %q, got %q", "hello world", got)
	}
}

// TestContentToStringEmbeddedResourceText surfaces the text of an embedded
// resource so it remains usable by the model.
func TestContentToStringEmbeddedResourceText(t *testing.T) {
	content := []mcp.Content{
		&mcp.EmbeddedResource{Resource: &mcp.ResourceContents{URI: "file://x", Text: "embedded body"}},
	}

	if got := contentToString(content); !strings.Contains(got, "embedded body") {
		t.Fatalf("expected embedded resource text in result, got %q", got)
	}
}

// TestContentToStringAudioAndResourceLink ensures the remaining non-text content
// variants are summarized rather than panicking.
func TestContentToStringAudioAndResourceLink(t *testing.T) {
	content := []mcp.Content{
		&mcp.AudioContent{MIMEType: "audio/wav", Data: []byte("RIFFfake")},
		&mcp.ResourceLink{URI: "https://example.com/r"},
	}

	got := contentToString(content)
	if !strings.Contains(got, "audio/wav") {
		t.Fatalf("expected audio mime type in result, got %q", got)
	}
	if !strings.Contains(got, "https://example.com/r") {
		t.Fatalf("expected resource link URI in result, got %q", got)
	}
}

package cogito

import (
	"context"
	"sync"
	"testing"
)

// TestWithAgentSpawnCallbackStores asserts the option stores the fn on Options.
func TestWithAgentSpawnCallbackStores(t *testing.T) {
	o := defaultOptions()
	o.Apply(WithAgentSpawnCallback(func(*AgentState) {}))
	if o.agentSpawnCallback == nil {
		t.Fatal("spawn callback not stored")
	}
}

// TestSpawnCallbackFiresForeground asserts a foreground spawn fires the spawn
// callback with a running AgentState whose Type matches the requested type.
func TestSpawnCallbackFiresForeground(t *testing.T) {
	var mu sync.Mutex
	var fired bool
	var gotStatus AgentStatusType
	var gotType string
	var nonNil bool

	defs := []AgentDefinition{{Name: "explore", SystemPrompt: "You are EXPLORE."}}
	runner := &spawnAgentRunner{
		llm:              newReplyLLM("foreground done"),
		manager:          NewAgentManager(),
		ctx:              context.Background(),
		agentDefinitions: defs,
		// Snapshot the AgentState fields at callback time. The foreground agent
		// runs in a goroutine and may mutate Status to "completed" by the time
		// Run returns, so we must capture the values inside the callback (while
		// Status is still running) rather than reading the live pointer after.
		agentSpawnCallback: func(a *AgentState) {
			mu.Lock()
			fired = true
			nonNil = a != nil
			if a != nil {
				gotStatus = a.Status
				gotType = a.Type
			}
			mu.Unlock()
		},
	}

	_, _, err := runner.Run(SpawnAgentArgs{AgentType: "explore", Task: "look around", Background: false})
	if err != nil {
		t.Fatalf("foreground spawn errored: %v", err)
	}

	mu.Lock()
	defer mu.Unlock()
	if !fired {
		t.Fatal("spawn callback did not fire for foreground spawn")
	}
	if !nonNil {
		t.Fatal("spawn callback received a nil AgentState")
	}
	if gotStatus != AgentStatusRunning {
		t.Fatalf("spawn callback AgentState status = %q, want %q", gotStatus, AgentStatusRunning)
	}
	if gotType != "explore" {
		t.Fatalf("spawn callback AgentState type = %q, want %q", gotType, "explore")
	}
}

// TestSpawnCallbackFiresBackground asserts a background spawn fires the spawn
// callback synchronously (before Run returns the ID) with a running AgentState
// whose Type matches the requested type.
func TestSpawnCallbackFiresBackground(t *testing.T) {
	var mu sync.Mutex
	var fired bool
	var gotStatus AgentStatusType
	var gotType string
	var nonNil bool

	defs := []AgentDefinition{{Name: "plan", SystemPrompt: "You are PLAN."}}
	runner := &spawnAgentRunner{
		llm:              newReplyLLM("background done"),
		manager:          NewAgentManager(),
		ctx:              context.Background(),
		agentDefinitions: defs,
		// The background spawn fires the callback synchronously (before Run
		// returns the ID) while Status is still running, but the agent's
		// goroutine may mutate Status afterward, so snapshot inside the callback.
		agentSpawnCallback: func(a *AgentState) {
			mu.Lock()
			fired = true
			nonNil = a != nil
			if a != nil {
				gotStatus = a.Status
				gotType = a.Type
			}
			mu.Unlock()
		},
	}

	out, _, err := runner.Run(SpawnAgentArgs{AgentType: "plan", Task: "make a plan", Background: true})
	if err != nil {
		t.Fatalf("background spawn errored: %v", err)
	}
	_ = out

	mu.Lock()
	defer mu.Unlock()
	if !fired {
		t.Fatal("spawn callback did not fire for background spawn")
	}
	if !nonNil {
		t.Fatal("spawn callback received a nil AgentState")
	}
	if gotStatus != AgentStatusRunning {
		t.Fatalf("spawn callback AgentState status = %q, want %q", gotStatus, AgentStatusRunning)
	}
	if gotType != "plan" {
		t.Fatalf("spawn callback AgentState type = %q, want %q", gotType, "plan")
	}
}

