import (
	"context"
	"encoding/json"
	"reflect"
	"testing"
	"time"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

// Test the discovery boundary, not a hand-built approximation of Parameters.
func TestMCPDiscoveryPreservesInputSchema(t *testing.T) {
	cases := map[string]string{
		"nullable enum and defaults":         `{"type":"object","properties":{"status":{"anyOf":[{"enum":["pending","shipped","delivered","cancelled"],"type":"string"},{"type":"null"}],"default":null},"limit":{"default":20,"type":"integer"}}}`,
		"root references and compositions":   `{"type":"object","$schema":"https://json-schema.org/draft/2020-12/schema","$defs":{"args":{"type":"object","properties":{"id":{"type":"integer","minimum":1}}}},"$ref":"#/$defs/args","allOf":[{"required":["id"]}],"anyOf":[{"required":["id"]},false],"oneOf":[{"required":["id"]}],"unevaluatedProperties":false,"title":"Arguments","x-extension":{"enabled":false}}`,
		"nullable types and boolean schemas": `{"type":"object","properties":{"tags":{"type":["null","array"],"items":{"type":["string","null"]}},"rows":{"type":"array","items":{"type":"array","items":true}},"never":false,"anything":true,"closed":{"type":"object","additionalProperties":false},"flag":{"type":"boolean","default":false},"tuple":{"prefixItems":[true,false],"items":false}},"additionalProperties":false}`,
		"nested constraints":                 `{"type":"object","properties":{"config":{"type":"object","patternProperties":{"^x":{"type":["string","null"]}},"additionalProperties":{"type":"integer"},"dependentSchemas":{"x":{"required":["y"]}},"propertyNames":{"minLength":1}},"values":{"type":"array","contains":{"const":0},"minContains":1,"maxItems":10,"uniqueItems":true,"items":{"anyOf":[{"type":"integer"},false]}}},"if":{"required":["config"]},"then":{"required":["values"]},"else":{"not":{"required":["values"]}},"required":[]}`,
		"no arguments absent properties":     `{"type":"object"}`,
		"no arguments explicit properties":   `{"type":"object","properties":{},"additionalProperties":false}`,
	}
	for name, schema := range cases {
		t.Run(name, func(t *testing.T) {
			ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
			defer cancel()
			impl := &mcp.Implementation{Name: "schema-test", Version: "1"}
			server := mcp.NewServer(impl, nil)
			server.AddTool(&mcp.Tool{Name: "example", Description: "Example tool", InputSchema: json.RawMessage(schema)}, func(context.Context, *mcp.CallToolRequest) (*mcp.CallToolResult, error) {
				return &mcp.CallToolResult{}, nil
			})
			st, ct := mcp.NewInMemoryTransports()
			ss, err := server.Connect(ctx, st, nil)
			if err != nil {
				t.Fatal(err)
			}
			defer ss.Close()
			session, err := mcp.NewClient(impl, nil).Connect(ctx, ct, nil)
			if err != nil {
				t.Fatal(err)
			}
			defer session.Close()
			tools, err := mcpToolsFromTransport(ctx, session, nil)
			if err != nil {
				t.Fatal(err)
			}
			if len(tools) != 1 {
				t.Fatalf("discovered %d tools, want 1", len(tools))
			}
			tool := tools[0].Tool()
			if tool.Function.Name != "example" || tool.Function.Description != "Example tool" {
				t.Fatalf("tool metadata changed: %+v", tool)
			}
			got, err := json.Marshal(tool.Function.Parameters)
			if err != nil {
				t.Fatal(err)
			}
			var wantValue, gotValue any
			if err := json.Unmarshal([]byte(schema), &wantValue); err != nil {
				t.Fatal(err)
			}
			if err := json.Unmarshal(got, &gotValue); err != nil {
				t.Fatal(err)
			}
			if !reflect.DeepEqual(wantValue, gotValue) {
				t.Fatalf("schema changed during discovery:\nwant %s\n got %s", schema, got)
			}
		})
	}
}

package cogito

import (
	"context"
	"fmt"
	"github.com/sashabaranov/go-openai"
	"runtime"
	"strings"
	"time"
)

// CompleteAgentFixture mirrors terminal publication without adding production API.
func CompleteAgentFixture(m *AgentManager, id, result string) {
	m.mu.Lock()
	a := m.agents[id]
	a.Status, a.Result = AgentStatusCompleted, result
	done := a.done
	m.mu.Unlock()
	close(done)
}

// AwaitAgentFixtureWait observes an actually blocked reader, not a timed sleep.
// Like TestGetAgentResultConcurrentCompletion, stack observation does not mask
// a missing synchronization edge between the reader and terminal publication.
func AwaitAgentFixtureWait(symbol string) error {
	deadline := time.Now().Add(5 * time.Second)
	stack := make([]byte, 1<<20)
	for time.Now().Before(deadline) {
		n := runtime.Stack(stack, true)
		for _, g := range strings.Split(string(stack[:n]), "\n\n") {
			if strings.Contains(g, symbol) && (strings.Contains(g, "[select]") || strings.Contains(g, "[chan receive]")) {
				return nil
			}
		}
		runtime.Gosched()
	}
	return fmt.Errorf("reader did not block in %s", symbol)
}

// CheckAgentPublicationAtomicity pins a manager reader across publication.
// A notice must not become visible while its pending flag cannot be cleared.
func CheckAgentPublicationAtomicity() error {
	m := NewAgentManager()
	a := &AgentState{ID: "publication", Status: AgentStatusRunning, Background: true, done: make(chan struct{})}
	m.Register(a)
	injected := make(chan openai.ChatCompletionMessage, 1)
	formatting, release, finished := make(chan struct{}), make(chan struct{}), make(chan struct{})
	r := &spawnAgentRunner{manager: m, messageInjectionChan: injected,
		dispatcher: func(context.Context, AgentRunSpec) (Fragment, error) {
			return NewEmptyFragment().AddMessage(AssistantMessageRole, "answer"), nil
		},
		completionFormatter: func(*AgentState) string { close(formatting); <-release; return "notice" },
	}
	go func() {
		r.runAgent(a, nil, Fragment{}, nil, AgentRunSpec{}, context.Background(), func() {})
		close(finished)
	}()
	<-formatting
	m.mu.RLock()
	close(release)
	// Both implementations reach the writer lock: the old one sends first,
	// whereas the fixed one acquires the lock before exposing the notification.
	deadline := time.Now().Add(5 * time.Second)
	stack := make([]byte, 1<<20)
	blocked := false
	for time.Now().Before(deadline) {
		n := runtime.Stack(stack, true)
		for _, g := range strings.Split(string(stack[:n]), "\n\n") {
			if strings.Contains(g, "(*spawnAgentRunner).runAgent(") && strings.Contains(g, "sync.(*RWMutex).Lock(") {
				blocked = true
				break
			}
		}
		if blocked {
			break
		}
		runtime.Gosched()
	}
	visible := len(injected)
	m.mu.RUnlock()
	<-finished
	if !blocked {
		return fmt.Errorf("publisher did not reach manager writer lock")
	}
	if visible != 0 {
		return fmt.Errorf("completion became visible before pending state could be cleared")
	}
	if len(injected) != 1 || m.HasRunning() {
		return fmt.Errorf("completion was not delivered exactly once with pending cleared")
	}
	return nil
}

package cogito

// These tests retain compatibility coverage for the deprecated normalization
// helper. MCP discovery does not use it; mcp_schema_test.go covers preservation.

import (
	"encoding/json"
	"testing"

	"github.com/tmc/langchaingo/jsonschema"
)

// containsBoolSchema reports whether any schema-valued slot in v is still a
// JSON boolean (i.e. the normalization missed it). Mirrors containsTypeArray.
func containsBoolSchema(v any) bool {
	// Keywords whose value IS a schema, so a bool there is a boolean schema.
	// "properties"/"$defs" etc. are bags of schemas and handled by recursion.
	single := []string{"items", "additionalProperties", "contains", "not",
		"if", "then", "else", "propertyNames"}
	switch n := v.(type) {
	case map[string]any:
		for _, k := range single {
			if _, ok := n[k].(bool); ok {
				return true
			}
		}
		for _, child := range n {
			if containsBoolSchema(child) {
				return true
			}
		}
	case []any:
		for _, child := range n {
			if containsBoolSchema(child) {
				return true
			}
		}
	}
	return false
}

// JSON Schema 2020-12 lets any schema be the boolean `true` ("allow anything")
// or `false` ("allow nothing"), and google/jsonschema-go emits exactly that for
// a Go `any` — an empty schema marshals as `true`. langchaingo's
// jsonschema.Definition models every nested schema as a *Definition, so a bool
// fails the unmarshal and mcpToolsFromTransport drops the ENTIRE tool with a
// single log line. The server is healthy and its tool simply never reaches the
// model. Same failure class as the type-array coercion next door.
func TestCoerceBooleanSchemas(t *testing.T) {
	cases := []struct {
		name string
		in   string
	}{
		{
			// The real-world shape that surfaced this: Go [][]any (rows of
			// cells) infers `items: true` for the innermost element.
			name: "items true nested in array of arrays",
			in:   `{"rows":{"type":"array","items":{"type":"array","items":true}}}`,
		},
		{
			name: "additionalProperties false",
			in:   `{"cfg":{"type":"object","additionalProperties":false}}`,
		},
		{
			name: "bool schema inside properties",
			in:   `{"outer":{"type":"object","properties":{"anything":true}}}`,
		},
		{
			name: "bool schema in composition keyword",
			in:   `{"x":{"anyOf":[true,{"type":"string"}]}}`,
		},
		{
			name: "bool schema in $defs and prefixItems",
			in:   `{"x":{"$defs":{"any":true},"prefixItems":[true,{"type":"string"}]}}`,
		},
		{
			name: "false schema is preserved as allow-nothing",
			in:   `{"never":{"type":"array","items":false}}`,
		},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			var props map[string]any
			if err := json.Unmarshal([]byte(tc.in), &props); err != nil {
				t.Fatalf("bad test fixture: %v", err)
			}

			coerceNullableTypes(props)

			if containsBoolSchema(props) {
				got, _ := json.Marshal(props)
				t.Errorf("a boolean schema survived normalization: %s", got)
			}

			// The point of the exercise: cogito must be able to convert the
			// result into langchaingo Definitions, or it drops the tool.
			dat, err := json.Marshal(props)
			if err != nil {
				t.Fatalf("marshal: %v", err)
			}
			defs := map[string]jsonschema.Definition{}
			if err := json.Unmarshal(dat, &defs); err != nil {
				t.Errorf("tool would be DROPPED — properties do not convert to langchaingo Definitions: %v\ngot: %s", err, dat)
			}
		})
	}
}

// `true` means "anything allowed" and `false` means "nothing allowed". The
// rewrite must preserve that distinction rather than flattening both to an
// empty schema, which would silently widen a deliberately-closed schema.
func TestBooleanSchemaSemanticsPreserved(t *testing.T) {
	var props map[string]any
	if err := json.Unmarshal([]byte(`{"a":{"items":true},"b":{"items":false}}`), &props); err != nil {
		t.Fatal(err)
	}
	coerceNullableTypes(props)

	a := props["a"].(map[string]any)["items"]
	if m, ok := a.(map[string]any); !ok || len(m) != 0 {
		t.Errorf(`items:true must become the empty schema {} (allow anything), got %#v`, a)
	}

	b := props["b"].(map[string]any)["items"]
	m, ok := b.(map[string]any)
	if !ok {
		t.Fatalf(`items:false must become an object, got %#v`, b)
	}
	if _, hasNot := m["not"]; !hasNot {
		t.Errorf(`items:false must become {"not":{}} (allow nothing), got %#v`, m)
	}
}

// Normalization must not disturb a schema that was already convertible.
func TestNormalizationLeavesPlainSchemasAlone(t *testing.T) {
	const in = `{"name":{"type":"string","description":"a name"},"tags":{"type":"array","items":{"type":"string"}}}`
	var props map[string]any
	if err := json.Unmarshal([]byte(in), &props); err != nil {
		t.Fatal(err)
	}
	coerceNullableTypes(props)

	got, err := json.Marshal(props)
	if err != nil {
		t.Fatal(err)
	}
	var want, have any
	_ = json.Unmarshal([]byte(in), &want)
	_ = json.Unmarshal(got, &have)
	if string(got) == "" || !jsonEqual(want, have) {
		t.Errorf("plain schema was modified:\n want %s\n  got %s", in, got)
	}
}

func jsonEqual(a, b any) bool {
	x, _ := json.Marshal(a)
	y, _ := json.Marshal(b)
	return string(x) == string(y)
}

