func TestAgentToolsCopiesAndReconstruction(t *testing.T) {
	names := []string{"check_agent"}
	opt := WithAgentTools(names)
	names[0] = "send_agent_message"
	o := defaultOptions()
	o.Apply(opt)
	o.agentTools[0] = "spawn_agent"
