package cogito

import (
	"context"
	"strings"
	"testing"
	"time"

	"github.com/sashabaranov/go-openai"
)

// blockingLLM blocks in CreateChatCompletion until release is closed, then
// returns a plain (tool-less) reply so the agent loop terminates. It models a
// long-running foreground sub-agent that an embedder can promote to background.
type blockingLLM struct {
	release chan struct{}
	reply   string
}

// newBlockingLLM builds an LLM whose tool-selection turn blocks on <-release
// before returning a sink reply. Used by the detach test to keep a foreground
// agent in-flight while the parent detaches it.
func newBlockingLLM(release chan struct{}) *blockingLLM {
	return &blockingLLM{release: release, reply: "blocked done"}
}

func (m *blockingLLM) Ask(_ context.Context, f Fragment) (Fragment, error) {
	return f.AddMessage(AssistantMessageRole, m.reply), nil
}

func (m *blockingLLM) CreateChatCompletion(ctx context.Context, _ openai.ChatCompletionRequest) (LLMReply, LLMUsage, error) {
	select {
	case <-m.release:
	case <-ctx.Done():
		return LLMReply{}, LLMUsage{}, ctx.Err()
	}
	return LLMReply{ChatCompletionResponse: openai.ChatCompletionResponse{
		Choices: []openai.ChatCompletionChoice{{
			Message: openai.ChatCompletionMessage{Role: AssistantMessageRole.String(), Content: m.reply},
		}},
	}}, LLMUsage{}, nil
}

func TestDetachReturnsBeforeCompletion(t *testing.T) {
	m := NewAgentManager()
	release := make(chan struct{})
	// An LLM that blocks until released, simulating a long-running foreground agent.
	llm := newBlockingLLM(release)

	runner := &spawnAgentRunner{
		llm: llm, manager: m, ctx: context.Background(),
	}

	type res struct {
		out string
		id  any
	}
	resCh := make(chan res, 1)
	go func() {
		out, id, _ := runner.Run(SpawnAgentArgs{Task: "long job", Background: false})
		resCh <- res{out, id}
	}()

	// Wait for the foreground agent to register, then detach it.
	var id string
	deadline := time.After(2 * time.Second)
	for {
		agents := m.List()
		if len(agents) == 1 {
			id = agents[0].ID
			break
		}
		select {
		case <-deadline:
			t.Fatal("foreground agent never registered")
		case <-time.After(10 * time.Millisecond):
		}
	}

	if err := m.Detach(id); err != nil {
		t.Fatalf("detach errored: %v", err)
	}

	select {
	case r := <-resCh:
		if r.id == nil {
			t.Fatal("expected detach to return the agent id")
		}
	case <-time.After(2 * time.Second):
		t.Fatal("Run did not return after detach")
	}

	// The goroutine is still running; release it so the test can clean up.
	close(release)
}

func TestDetachUnknownAgentErrors(t *testing.T) {
	m := NewAgentManager()
	if err := m.Detach("missing"); err == nil {
		t.Fatal("expected error for unknown agent")
	}
}

func TestDetachNonDetachableAgentErrors(t *testing.T) {
	m := NewAgentManager()
	// A background-style agent has no detach channel: it is already detached.
	agent := &AgentState{ID: "bg1", Status: AgentStatusRunning, done: make(chan struct{})}
	m.Register(agent)
	if err := m.Detach("bg1"); err == nil {
		t.Fatal("expected error for non-detachable agent")
	}
}

// TestForegroundSpawnUnchangedWithoutDetach is the key safety property: when no
// detach ever fires, the foreground select returns on agent.done and yields the
// same result content the old synchronous path returned via
// result.LastMessage().Content. The plan sketch used
// newScriptedLLM(scriptReply("final answer")); that signature does not exist in
// this repo, so we use the reply-only newReplyLLM helper (added in A8), which
// terminates the loop immediately with the fixed reply.
func TestForegroundSpawnUnchangedWithoutDetach(t *testing.T) {
	m := NewAgentManager()
	llm := newReplyLLM("final answer")
	runner := &spawnAgentRunner{llm: llm, manager: m, ctx: context.Background()}
	out, _, err := runner.Run(SpawnAgentArgs{Task: "quick", Background: false})
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if !strings.Contains(out, "final answer") {
		t.Fatalf("foreground result changed, got %q", out)
	}
}

package cogito

// These tests retain compatibility coverage for the deprecated normalization
// helper. MCP discovery does not use it; mcp_schema_test.go covers preservation.

import (
	"encoding/json"
	"testing"

	"github.com/tmc/langchaingo/jsonschema"
)

// containsTypeArray returns true if any nested node in v still carries
// a JSON-array `type` (i.e. coerce missed it). Used by tests to assert
// the coerce reaches every corner of a schema.
func containsTypeArray(v any) bool {
	switch n := v.(type) {
	case map[string]any:
		if _, ok := n["type"].([]any); ok {
			return true
		}
		for _, child := range n {
			if containsTypeArray(child) {
				return true
			}
		}
	case []any:
		for _, child := range n {
			if containsTypeArray(child) {
				return true
			}
		}
	}
	return false
}

// TestCoerceNullableTypes pins the workaround for
// modelcontextprotocol/go-sdk v1.4+ schemas that emit
// "type": ["null", "X"] for nullable Go fields like []string slices.
// Without coercion, tools with such fields silently drop out of the
// agent's tool list because langchaingo/jsonschema.Definition.Type
// is a single string and the JSON-array form fails to unmarshal.
func TestCoerceNullableTypes(t *testing.T) {
	cases := []struct {
		name string
		in   string
		want string
		// langchaingoCompatible reports whether the test's schema
		// shape is one langchaingo's Definition struct can represent.
		// Tuple-style `items: [...]` and other JSON Schema 2020-12
		// constructs aren't representable but we still want coerce
		// to walk into them; for those, skip the round-trip and
		// keep just the deep-walk assertion.
		langchaingoCompatible bool
	}{
		{
			name:                  "nullable array stays as array",
			in:                    `{"tags": {"type": ["null", "array"], "items": {"type": "string"}}}`,
			want:                  "array",
			langchaingoCompatible: true,
		},
		{
			name:                  "nullable string stays as string",
			in:                    `{"name": {"type": ["null", "string"]}}`,
			want:                  "string",
			langchaingoCompatible: true,
		},
		{
			name:                  "single string type passes through",
			in:                    `{"name": {"type": "string"}}`,
			want:                  "string",
			langchaingoCompatible: true,
		},
		{
			name: "nested properties are coerced too",
			in: `{"obj": {
				"type": "object",
				"properties": {"inner": {"type": ["null", "string"]}}
			}}`,
			want:                  "object",
			langchaingoCompatible: true,
		},
		{
			name: "oneOf member with nullable type",
			in: `{"v": {"oneOf": [
				{"type": ["null", "string"]},
				{"type": ["null", "integer"]}
			]}}`,
			// langchaingo's Definition has no oneOf — round-trip
			// drops the field but coerce should still reach inside.
		},
		{
			name: "anyOf member with nullable type",
			in:   `{"v": {"anyOf": [{"type": ["null", "boolean"]}]}}`,
		},
		{
			name: "allOf member with nullable type",
			in: `{"v": {"allOf": [
				{"type": ["null", "object"], "properties": {"x": {"type": ["null", "string"]}}}
			]}}`,
		},
		{
			name: "items as schema array (tuple)",
			in: `{"v": {"type": "array", "items": [
				{"type": ["null", "string"]},
				{"type": ["null", "integer"]}
			]}}`,
			// langchaingo's Items is a single *Definition, not an
			// array — the tuple shape isn't representable. Coerce
			// still has to walk into it though.
		},
		{
			name:                  "additionalProperties schema",
			in:                    `{"v": {"type": "object", "additionalProperties": {"type": ["null", "string"]}}}`,
			want:                  "object",
			langchaingoCompatible: true,
		},
		{
			name: "$defs nested",
			in: `{"v": {
				"type": "object",
				"$defs": {"named": {"type": ["null", "string"]}}
			}}`,
			want:                  "object",
			langchaingoCompatible: true,
		},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			var props map[string]any
			if err := json.Unmarshal([]byte(tc.in), &props); err != nil {
				t.Fatalf("unmarshal: %v", err)
			}
			coerceNullableTypes(props)

			// Universal assertion: deep walk leaves ZERO JSON-array
			// type nodes anywhere — properties, items, oneOf, anyOf,
			// allOf, additionalProperties, $defs. This is the
			// failure mode that silently dropped tools in prod;
			// the recursion has to reach every corner.
			if containsTypeArray(props) {
				dump, _ := json.MarshalIndent(props, "", "  ")
				t.Errorf("residual JSON-array type in coerced schema:\n%s", string(dump))
			}

			// langchaingo round-trip — only when the schema shape
			// is representable. JSON-Schema 2020-12 has constructs
			// (oneOf, tuple items, etc.) langchaingo can't model.
			if !tc.langchaingoCompatible {
				return
			}
			b, err := json.Marshal(props)
			if err != nil {
				t.Fatalf("re-marshal: %v", err)
			}
			out := map[string]jsonschema.Definition{}
			if err := json.Unmarshal(b, &out); err != nil {
				t.Fatalf("post-coerce unmarshal into jsonschema.Definition: %v", err)
			}
			if tc.want != "" {
				for _, def := range out {
					if string(def.Type) != tc.want {
						t.Errorf("got type=%q, want %q", def.Type, tc.want)
					}
				}
			}
			// Nested-properties case: assert the inner field too.
			if tc.name == "nested properties are coerced too" {
				obj := out["obj"]
				inner := obj.Properties["inner"]
				if string(inner.Type) != "string" {
					t.Errorf("nested inner type=%q, want string", inner.Type)
				}
			}
		})
	}
}

package cogito

import (
	"context"
	"sync"
	"testing"

	"github.com/sashabaranov/go-openai"
)

func TestSessionStateHasAgentID(t *testing.T) {
	s := SessionState{AgentID: "abc-123"}
	if s.AgentID != "abc-123" {
		t.Fatalf("expected AgentID to round-trip, got %q", s.AgentID)
	}
}

// scriptedLLM is a minimal internal LLM mock for sub-agent tests. It drives a
// single tool call (via CreateChatCompletion) then a plain reply (via Ask),
// mirroring how the public mock.MockOpenAIClient is scripted in agent_test.go.
// We use an internal mock because these tests live in package cogito and need
// to construct spawnAgentRunner directly.
type scriptedLLM struct {
	mu       sync.Mutex
	toolName string
	toolArgs string
	reply    string
	called   bool
}

// newScriptedLLM builds an LLM that on its first tool-selection call selects
// toolName(toolArgs), and on the subsequent (post-tool) turn replies plainly.
func newScriptedLLM(toolName, toolArgs, reply string) *scriptedLLM {
	return &scriptedLLM{toolName: toolName, toolArgs: toolArgs, reply: reply}
}

func (m *scriptedLLM) Ask(_ context.Context, f Fragment) (Fragment, error) {
	return f.AddMessage(AssistantMessageRole, m.reply), nil
}

func (m *scriptedLLM) CreateChatCompletion(_ context.Context, _ openai.ChatCompletionRequest) (LLMReply, LLMUsage, error) {
	m.mu.Lock()
	defer m.mu.Unlock()
	if !m.called {
		m.called = true
		return LLMReply{ChatCompletionResponse: openai.ChatCompletionResponse{
			Choices: []openai.ChatCompletionChoice{{
				Message: openai.ChatCompletionMessage{
					Role: AssistantMessageRole.String(),
					ToolCalls: []openai.ToolCall{{
						Type: openai.ToolTypeFunction,
						Function: openai.FunctionCall{
							Name:      m.toolName,
							Arguments: m.toolArgs,
						},
					}},
				},
			}},
		}}, LLMUsage{}, nil
	}
	// No further tool calls: plain assistant message so the loop terminates.
	return LLMReply{ChatCompletionResponse: openai.ChatCompletionResponse{
		Choices: []openai.ChatCompletionChoice{{
			Message: openai.ChatCompletionMessage{Role: AssistantMessageRole.String(), Content: m.reply},
		}},
	}}, LLMUsage{}, nil
}

// echoRunner is a trivial tool that records how many times it ran. The counter
// lets tests assert the tool executed (approve path) or did not (reject path).
type echoRunner struct {
	mu    *sync.Mutex
	count *int
}

func (r echoRunner) Run(EchoArgs) (string, any, error) {
	r.mu.Lock()
	*r.count++
	r.mu.Unlock()
	return "echo", nil, nil
}

// EchoArgs is the argument type for the echo test tool.
type EchoArgs struct {
	Text string `json:"text" description:"text to echo"`
}

// newEchoTool builds an echo tool whose invocation count is tracked via the
// supplied mutex+counter.
func newEchoTool(mu *sync.Mutex, count *int) ToolDefinitionInterface {
	return NewToolDefinition[EchoArgs](
		echoRunner{mu: mu, count: count},
		EchoArgs{},
		"echo",
		"echo text",
	)
}

func TestSubAgentToolCallReachesParentCallback(t *testing.T) {
	var mu sync.Mutex
	var seenAgentIDs []string

	parentCB := func(tc *ToolChoice, st *SessionState) ToolCallDecision {
		mu.Lock()
		seenAgentIDs = append(seenAgentIDs, st.AgentID)
		mu.Unlock()
		return ToolCallDecision{Approved: true}
	}

	var echoMu sync.Mutex
	echoCount := 0
	echo := newEchoTool(&echoMu, &echoCount)
	llm := newScriptedLLM("echo", `{"text": "hi"}`, "done")

	runner := &spawnAgentRunner{
		llm:         llm,
		parentTools: Tools{echo},
		parentOpts:  []Option{WithToolCallBack(parentCB)},
		manager:     NewAgentManager(),
		ctx:         context.Background(),
	}

	_, _, err := runner.Run(SpawnAgentArgs{Task: "say hi", Background: false})
	if err != nil {
		t.Fatalf("foreground spawn errored: %v", err)
	}

	mu.Lock()
	defer mu.Unlock()
	if len(seenAgentIDs) == 0 {
		t.Fatal("parent tool callback was never invoked from the sub-agent")
	}
	for _, id := range seenAgentIDs {
		if id == "" {
			t.Fatal("expected a non-empty AgentID in sub-agent tool callback")
		}
	}

	echoMu.Lock()
	defer echoMu.Unlock()
	if echoCount != 1 {
		t.Fatalf("expected approved echo tool to run exactly once, ran %d times", echoCount)
	}
}

func TestSubAgentToolRejectionIsHonored(t *testing.T) {
	rejectCB := func(tc *ToolChoice, st *SessionState) ToolCallDecision {
		return ToolCallDecision{Approved: false}
	}

	var echoMu sync.Mutex
	echoCount := 0
	echo := newEchoTool(&echoMu, &echoCount)
	llm := newScriptedLLM("echo", `{"text": "hi"}`, "done")

	runner := &spawnAgentRunner{
		llm:         llm,
		parentTools: Tools{echo},
		parentOpts:  []Option{WithToolCallBack(rejectCB)},
		manager:     NewAgentManager(),
		ctx:         context.Background(),
	}

	_, _, err := runner.Run(SpawnAgentArgs{Task: "say hi", Background: false})
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	echoMu.Lock()
	defer echoMu.Unlock()
	if echoCount != 0 {
		t.Fatalf("rejected echo tool must not run, ran %d times", echoCount)
	}
}

