package cogito

import (
	"context"
	"fmt"
	"sync"
	"sync/atomic"
	"testing"
	"time"

	"github.com/sashabaranov/go-openai"
)

type lifecycleParentLLM struct {
	calls           int
	callbackEntered <-chan struct{}
}

func (m *lifecycleParentLLM) Ask(context.Context, Fragment) (Fragment, error) {
	return Fragment{}, fmt.Errorf("unexpected Ask")
}
func (m *lifecycleParentLLM) CreateChatCompletion(ctx context.Context, _ openai.ChatCompletionRequest) (LLMReply, LLMUsage, error) {
	m.calls++
	msg := openai.ChatCompletionMessage{Role: "assistant", Content: "parent done"}
	switch m.calls {
	case 1:
		msg.Content = ""
		msg.ToolCalls = []openai.ToolCall{{ID: "spawn", Type: openai.ToolTypeFunction, Function: openai.FunctionCall{Name: "spawn_agent", Arguments: `{"task":"child"}`}}}
	case 2:
		select {
		case <-m.callbackEntered:
		case <-ctx.Done():
			return LLMReply{}, LLMUsage{}, ctx.Err()
		}
	default:
		return LLMReply{}, LLMUsage{}, fmt.Errorf("duplicate parent selection %d", m.calls)
	}
	return LLMReply{ChatCompletionResponse: openai.ChatCompletionResponse{Choices: []openai.ChatCompletionChoice{{Message: msg}}}}, LLMUsage{}, nil
}

func TestAgentForegroundNoDuplicateParentNotification(t *testing.T) {
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	entered, release := make(chan struct{}), make(chan struct{})
	var once sync.Once
	unblock := func() { once.Do(func() { close(release) }) }
	defer unblock()
	llm := &lifecycleParentLLM{callbackEntered: entered}
	manager := NewAgentManager()
	var parked atomic.Int32
	result, err := ExecuteTools(llm, NewEmptyFragment().AddMessage(UserMessageRole, "start"),
		WithContext(ctx), EnableAgentSpawning, WithAgentManager(manager), WithIterations(3),
		WithAgentDispatcher(func(context.Context, AgentRunSpec) (Fragment, error) {
			return NewEmptyFragment().AddMessage(AssistantMessageRole, "child done"), nil
		}),
		WithAgentCompletionCallback(func(*AgentState) { close(entered); <-release }),
		WithOnPark(func(string) { parked.Add(1); unblock() }),
	)
	if err != nil {
		t.Fatalf("foreground parent failed: %v", err)
	}
	if parked.Load() != 0 || llm.calls != 2 {
		t.Fatalf("foreground parked %d times, selected %d times", parked.Load(), llm.calls)
	}
	if result.LastMessage().Content != "parent done" || len(result.Status.InjectedMessages) != 0 {
		t.Fatalf("unexpected parent result: %+v", result)
	}
}

// Gate callbacks after done closes: Wait must finish promptly, while only
// asynchronous deliveries may keep the manager pending until publication.
func TestAgentCompletionDeliveryModes(t *testing.T) {
	for _, mode := range []string{"foreground", "background", "detached"} {
		t.Run(mode, func(t *testing.T) {
			ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
			defer cancel()
			m := NewAgentManager()
			a := &AgentState{ID: "child", Status: AgentStatusRunning, Background: mode == "background", done: make(chan struct{}), detach: make(chan struct{}, 1)}
			m.Register(a)
			if mode == "detached" {
				if err := m.Detach(a.ID); err != nil {
					t.Fatal(err)
				}
			}
			entered, release, finished := make(chan struct{}), make(chan struct{}), make(chan struct{})
			var once sync.Once
			unblock := func() { once.Do(func() { close(release) }) }
			defer unblock()
			injected := make(chan openai.ChatCompletionMessage, 4)
			callbacks, formatted := 0, 0
			r := &spawnAgentRunner{manager: m, messageInjectionChan: injected,
				dispatcher: func(context.Context, AgentRunSpec) (Fragment, error) {
					return NewEmptyFragment().AddMessage(AssistantMessageRole, "answer"), nil
				},
				agentCompletionCallback: func(*AgentState) { callbacks++; close(entered); <-release },
				completionFormatter:     func(*AgentState) string { formatted++; return "notification" },
			}
			go func() { r.runAgent(a, nil, Fragment{}, nil, AgentRunSpec{}, ctx, func() {}); close(finished) }()
			select {
			case <-entered:
			case <-ctx.Done():
				t.Fatal("callback never reached")
			}
			type waitResult struct {
				agent *AgentState
				err   error
			}
			waited := make(chan waitResult, 1)
			go func() { got, err := m.Wait(a.ID); waited <- waitResult{got, err} }()
			select {
			case result := <-waited:
				if result.err != nil {
					t.Fatalf("Wait: %v", result.err)
				}
				got := result.agent
				if got.Result != "answer" {
					t.Fatal(got.Result)
				}
			case <-ctx.Done():
				t.Fatal("Wait blocked behind callback")
			}
			wantAsync := mode != "foreground"
			if pending := m.HasRunning(); pending != wantAsync {
				t.Errorf("pending=%v, want %v", pending, wantAsync)
			}
			unblock()
			select {
			case <-finished:
			case <-ctx.Done():
				t.Fatal("publication blocked")
			}
			want := 0
			if wantAsync {
				want = 1
			}
			if callbacks != 1 || formatted != want || len(injected) != want || m.HasRunning() {
				t.Fatalf("callbacks=%d formatted=%d notifications=%d pending=%v", callbacks, formatted, len(injected), m.HasRunning())
			}
		})
	}
}

func TestAgentForegroundConvertedToDetached(t *testing.T) {
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	manager := NewAgentManager()
	release := make(chan struct{})
	var once sync.Once
	unblock := func() { once.Do(func() { close(release) }) }
	defer unblock()
	injected := make(chan openai.ChatCompletionMessage, 2)
	spawned := make(chan string, 1)
	runner := &spawnAgentRunner{
		manager: manager, ctx: ctx, messageInjectionChan: injected,
		agentSpawnCallback: func(a *AgentState) { spawned <- a.ID },
		dispatcher: func(context.Context, AgentRunSpec) (Fragment, error) {
			<-release
			return NewEmptyFragment().AddMessage(AssistantMessageRole, "detached answer"), nil
		},
	}
	type response struct {
		text string
		data any
		err  error
	}
	returned := make(chan response, 1)
	go func() {
		text, data, err := runner.Run(SpawnAgentArgs{Task: "detach me"})
		returned <- response{text, data, err}
	}()
	var id string
	select {
	case id = <-spawned:
	case <-ctx.Done():
		t.Fatal("spawn blocked")
	}
	if err := manager.Detach(id); err != nil {
		t.Fatal(err)
	}
	// The caller must return an ID without waiting for child completion.
	select {
	case got := <-returned:
		if got.err != nil || got.data != id || got.text != "Agent detached to background with ID: "+id {
			t.Fatalf("detach result: %+v", got)
		}
	case <-ctx.Done():
		t.Fatal("detach did not release caller")
	}
	unblock()
	select {
	case msg := <-injected:
		if msg.Name != agentCompletionMessageName {
			t.Fatalf("unexpected notification: %+v", msg)
		}
	case <-ctx.Done():
		t.Fatal("detached completion not delivered")
	}
	got, err := manager.Wait(id)
	if err != nil || got.Result != "detached answer" {
		t.Fatalf("Wait result: %+v, %v", got, err)
	}
}

func TestAgentDetachAfterCompletionKeepsSynchronousDelivery(t *testing.T) {
	manager := NewAgentManager()
	agent := &AgentState{ID: "completed", Status: AgentStatusCompleted, done: make(chan struct{}), detach: make(chan struct{}, 1)}
	manager.Register(agent)
	if err := manager.Detach(agent.ID); err != nil {
		t.Fatal(err)
	}
	if agent.detached || len(agent.detach) != 0 {
		t.Fatal("late detach changed completion ownership")
	}
}

package cogito

import (
	"context"
	"errors"
	"strings"
	"sync/atomic"
	"testing"
	"time"

	"github.com/sashabaranov/go-openai"
)

type resumeObserverLLM struct {
	noToolMockLLM
	observed *atomic.Int32
	first    chan int32
}

func (m resumeObserverLLM) CreateChatCompletion(ctx context.Context, req openai.ChatCompletionRequest) (LLMReply, LLMUsage, error) {
	select {
	case m.first <- m.observed.Load():
	default:
	}
	return m.noToolMockLLM.CreateChatCompletion(ctx, req)
}
func (m resumeObserverLLM) Ask(ctx context.Context, f Fragment) (Fragment, error) {
	select {
	case m.first <- m.observed.Load():
	default:
	}
	return m.noToolMockLLM.Ask(ctx, f)
}

func TestAgentResumeCallbackBeforeRequestOutsideLock(t *testing.T) {
	for _, status := range []AgentStatusType{AgentStatusCompleted, AgentStatusFailed} {
		t.Run(string(status), func(t *testing.T) {
			manager := NewAgentManager()
			frag := NewEmptyFragment().AddMessage(UserMessageRole, "old task")
			manager.Register(&AgentState{ID: "child", Status: status, Fragment: &frag, done: closedChan()})
			before, _ := manager.Get("child")
			var calls, spawns atomic.Int32
			first := make(chan int32, 1)
			completed := make(chan struct{}, 1)
			o := defaultOptions()
			o.Apply(EnableAgentSpawning, WithContext(context.Background()), WithAgentManager(manager), WithIterations(1),
				WithAgentSpawnCallback(func(*AgentState) { spawns.Add(1) }),
				WithAgentCompletionCallback(func(*AgentState) { completed <- struct{}{} }),
				WithAgentResumeCallback(func(event AgentResumeEvent) {
					if event.ID != "child" || !event.Background {
						t.Errorf("event = %+v", event)
					}
					snapshot, ok := manager.Get(event.ID)
					if !ok || snapshot.Status != AgentStatusRunning || snapshot.Cancel == nil || snapshot.inject == nil || snapshot.done == before.done {
						t.Errorf("restart state not committed: %+v", snapshot)
					}
					select {
					case <-snapshot.done:
						t.Error("restart already done before observer")
					default:
					}
					snapshot.Fragment.Messages[0].Content = "snapshot mutation"
					stored, _ := manager.Get(event.ID)
					if stored.Fragment.Messages[0].Content != "old task" || before.Status != status {
						t.Error("observer snapshot aliases registry or prior snapshot")
					}
					// HasRunning takes the manager read lock: calling under its write lock deadlocks.
					if !manager.HasRunning() {
						t.Error("restart not registered before observer")
					}
					if err := manager.Inject(event.ID, "observer message"); err != nil {
						t.Error(err)
					}
					calls.Add(1)
				}))
			tools := prepareAgentTools(o, resumeObserverLLM{observed: &calls, first: first})
			returned := make(chan struct{})
			go func() {
				defer close(returned)
				_, _, err := Tools(tools).Find("send_agent_message").Execute(map[string]any{"agent_id": "child", "message": "continue"})
				if err != nil {
					t.Error(err)
				}
			}()
			select {
			case <-returned:
			case <-time.After(3 * time.Second):
				t.Fatal("observer blocked manager / restart")
			}
			select {
			case got := <-first:
				if got != 1 {
					t.Errorf("first child request saw %d resume events, want 1", got)
				}
			case <-time.After(3 * time.Second):
				t.Fatal("no child request")
			}
			select {
			case <-completed:
			case <-time.After(3 * time.Second):
				t.Fatal("child did not complete")
			}
			if calls.Load() != 1 || spawns.Load() != 0 {
				t.Fatalf("resume=%d spawn=%d", calls.Load(), spawns.Load())
			}
		})
	}
}

func TestAgentResumeCallbackRejectedAndLive(t *testing.T) {
	for _, mode := range []string{"missing", "no-context", "live", "live-full"} {
		t.Run(mode, func(t *testing.T) {
			manager := NewAgentManager()
			agent := &AgentState{ID: "child", Status: AgentStatusCompleted, inject: make(chan openai.ChatCompletionMessage, 1)}
			if strings.HasPrefix(mode, "live") {
				agent.Status = AgentStatusRunning
			}
			if mode == "live-full" {
				agent.inject <- openai.ChatCompletionMessage{Content: "full"}
			}
			if mode != "missing" {
				manager.Register(agent)
			}
			var calls atomic.Int32
			o := defaultOptions()
			o.Apply(EnableAgentSpawning, WithContext(context.Background()), WithAgentManager(manager), WithAgentResumeCallback(func(AgentResumeEvent) { calls.Add(1) }))
			tools := prepareAgentTools(o, noToolMockLLM{})
			_, _, err := Tools(tools).Find("send_agent_message").Execute(map[string]any{"agent_id": "child", "message": "continue"})
			if err != nil {
				t.Fatal(err)
			}
			if calls.Load() != 0 {
				t.Fatal("unexpected resume event")
			}
			if mode == "live" {
				select {
				case msg := <-agent.inject:
					if msg.Content != "continue" {
						t.Fatalf("injection = %+v", msg)
					}
				default:
					t.Fatal("no live injection")
				}
			}
		})
	}
}

func TestAgentResumeCallbackPropagatesToChildOptions(t *testing.T) {
	for _, toolName := range []string{"spawn_agent", "send_agent_message"} {
		t.Run(toolName, func(t *testing.T) {
			var calls atomic.Int32
			parent := defaultOptions()
			parent.Apply(EnableAgentSpawning, WithAgentResumeCallback(func(AgentResumeEvent) { calls.Add(1) }))
			tools := Tools(prepareAgentTools(parent, noToolMockLLM{}))
			var opts []Option
			if toolName == "spawn_agent" {
				opts = tools.Find(toolName).(*ToolDefinition[SpawnAgentArgs]).ToolRunner.(*spawnAgentRunner).parentOpts
			} else {
				opts = tools.Find(toolName).(*ToolDefinition[SendAgentMessageArgs]).ToolRunner.(*sendAgentMessageRunner).subOpts
			}
			child := defaultOptions()
			child.Apply(opts...)
			if child.agentResumeCallback == nil {
				t.Fatal("resume observer missing from child options")
			}
			child.agentResumeCallback(AgentResumeEvent{ID: "nested", Background: true})
			if calls.Load() != 1 {
				t.Fatal("child observer not connected to parent")
			}
		})
	}
}

// Cancellation remains a capability even though Get returns an owned snapshot.
func TestAgentResumeCallbackSnapshotCancel(t *testing.T) {
	manager := NewAgentManager()
	frag := NewEmptyFragment().AddMessage(UserMessageRole, "old task")
	manager.Register(&AgentState{ID: "child", Status: AgentStatusCompleted, Fragment: &frag})
	completed := make(chan *AgentState, 1)
	var calls atomic.Int32
	o := defaultOptions()
	o.Apply(EnableAgentSpawning, WithContext(context.Background()), WithAgentManager(manager),
		WithAgentCompletionCallback(func(a *AgentState) { completed <- a }),
		WithAgentResumeCallback(func(event AgentResumeEvent) {
			calls.Add(1)
			snapshot, _ := manager.Get(event.ID)
			snapshot.Cancel()
		}))
	llm := &blockingReplyLLM{started: make(chan struct{}), release: make(chan struct{}), reply: "unexpected"}
	tools := Tools(prepareAgentTools(o, llm))
	_, _, err := tools.Find("send_agent_message").Execute(map[string]any{"agent_id": "child", "message": "continue"})
	if err != nil {
		t.Fatal(err)
	}
	select {
	case state := <-completed:
		if calls.Load() != 1 || state.Status != AgentStatusFailed || !errors.Is(state.Error, context.Canceled) {
			t.Fatalf("resume calls=%d state=%+v", calls.Load(), state)
		}
	case <-time.After(3 * time.Second):
		close(llm.release)
		t.Fatal("snapshot Cancel did not cancel resumed execution")
	}
}

func TestAgentResumeCallbackNotInitialSpawn(t *testing.T) {
	var calls atomic.Int32
	o := defaultOptions()
	o.Apply(EnableAgentSpawning, WithContext(context.Background()), WithIterations(1),
		WithAgentResumeCallback(func(AgentResumeEvent) { calls.Add(1) }))
	tools := Tools(prepareAgentTools(o, noToolMockLLM{}))
	_, _, err := tools.Find("spawn_agent").Execute(map[string]any{"task": "initial task"})
	if err != nil {
		t.Fatal(err)
	}
	if calls.Load() != 0 {
		t.Fatal("initial spawn emitted resume event")
	}
}
